def minHammingDistance(source, target, allowedSwaps):
    n = len(source)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in allowedSwaps:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    counts = {}
    for i in range(n):
        d = counts.setdefault(find(i), {})
        d[source[i]] = d.get(source[i], 0) + 1
    dist = 0
    for j in range(n):
        d = counts[find(j)]
        if d.get(target[j], 0) > 0:
            d[target[j]] -= 1
        else:
            dist += 1
    return dist
